#include <bits/stdc++.h>
using namespace std;

class Solution {
public:
    int maxRepeating(string sequence, string word) {
        int n = sequence.size(), m = word.size(), best = 0;
        vector<int> dp(n + 1, 0);
        for (int i = m; i <= n; ++i) {
            if (sequence.compare(i - m, m, word) == 0) {
                dp[i] = dp[i - m] + 1;
                best = max(best, dp[i]);
            }
        }
        return best;
    }
};
